package com.seaoftales.identity.entity;
import com.seaoftales.identity.enums.InvitationType; import com.seaoftales.content.enums.Language;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="invitations", indexes=@Index(name="ix_invitation_token", columnList="tokenHash", unique=true))
public class Invitation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=128) private String tokenHash; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private InvitationType type; @Column(length=255) private String recipientEmail; @Enumerated(EnumType.STRING) @Column(length=20) private Language preferredLanguage; @Column(nullable=false) private Instant expiresAt; @Column(nullable=false) private boolean used; @Column(nullable=false) private Instant createdAt; private Instant usedAt;
 public Long getId(){return id;} public String getTokenHash(){return tokenHash;} public void setTokenHash(String v){tokenHash=v;} public InvitationType getType(){return type;} public void setType(InvitationType v){type=v;} public String getRecipientEmail(){return recipientEmail;} public void setRecipientEmail(String v){recipientEmail=v;} public Language getPreferredLanguage(){return preferredLanguage;} public void setPreferredLanguage(Language v){preferredLanguage=v;} public Instant getExpiresAt(){return expiresAt;} public void setExpiresAt(Instant v){expiresAt=v;} public boolean isUsed(){return used;} public void setUsed(boolean v){used=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUsedAt(){return usedAt;} public void setUsedAt(Instant v){usedAt=v;} }
